"use client"

import { useEffect, useRef, useCallback, memo } from "react"

interface Particle {
  x: number
  y: number
  vx: number
  vy: number
  radius: number
  color: string
  alpha: number
  pulsePhase: number
  pulseSpeed: number
}

interface ParticleCanvasProps {
  colors?: string[]
  connectionDistance?: number
  maxParticles?: number
  minParticles?: number
  neonScale?: number
  className?: string
}

const NEON_COLORS = ["#00f0ff", "#00d4ff", "#00ffcc", "#00ffc8", "#41ffdd"]
const CONNECTION_DISTANCE = 120
const PARTICLE_COUNT_FACTOR = 0.000035
const MAX_PARTICLES = 60
const MIN_PARTICLES = 15

export const ParticleCanvas = memo(function ParticleCanvas({
  colors = NEON_COLORS,
  connectionDistance = CONNECTION_DISTANCE,
  maxParticles = MAX_PARTICLES,
  minParticles = MIN_PARTICLES,
  neonScale = 1,
  className,
}: ParticleCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const particlesRef = useRef<Particle[]>([])
  const animFrameRef = useRef<number>(0)
  const mouseRef = useRef({ x: -1000, y: -1000 })

  const createParticles = useCallback(
    (width: number, height: number): Particle[] => {
      const area = width * height
      const count = Math.max(minParticles, Math.min(maxParticles, Math.floor(area * PARTICLE_COUNT_FACTOR)))
      return Array.from({ length: count }, () => ({
        x: Math.random() * width,
        y: Math.random() * height,
        vx: (Math.random() - 0.5) * 0.3,
        vy: (Math.random() - 0.5) * 0.3,
        radius: 1 + Math.random() * 2,
        color: colors[Math.floor(Math.random() * colors.length)],
        alpha: 0.15 + Math.random() * 0.35,
        pulsePhase: Math.random() * Math.PI * 2,
        pulseSpeed: 0.01 + Math.random() * 0.02,
      }))
    },
    [colors, maxParticles, minParticles],
  )

  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext("2d", { alpha: true })
    if (!ctx) return

    const resize = () => {
      const dpr = Math.min(window.devicePixelRatio || 1, 2)
      const parent = canvas.parentElement
      if (!parent) return
      const { width, height } = parent.getBoundingClientRect()
      canvas.width = width * dpr
      canvas.height = height * dpr
      canvas.style.width = `${width}px`
      canvas.style.height = `${height}px`
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
      particlesRef.current = createParticles(width, height)
    }

    resize()
    window.addEventListener("resize", resize)

    const handleMouse = (e: MouseEvent) => {
      mouseRef.current = { x: e.clientX, y: e.clientY }
    }
    const handleMouseLeave = () => {
      mouseRef.current = { x: -1000, y: -1000 }
    }
    window.addEventListener("mousemove", handleMouse)
    window.addEventListener("mouseleave", handleMouseLeave)

    const animate = () => {
      const { width, height } = canvas.getBoundingClientRect()
      ctx.clearRect(0, 0, width, height)
      const particles = particlesRef.current
      const mouse = mouseRef.current

      for (let i = 0; i < particles.length; i++) {
        const p = particles[i]
        p.pulsePhase += p.pulseSpeed
        const pulse = 0.6 + 0.4 * Math.sin(p.pulsePhase)

        const mdx = mouse.x - p.x
        const mdy = mouse.y - p.y
        const mDist = Math.sqrt(mdx * mdx + mdy * mdy)
        if (mDist < 150 && mDist > 1) {
          p.vx += (mdx / mDist) * 0.02
          p.vy += (mdy / mDist) * 0.02
        }

        p.vx *= 0.99
        p.vy *= 0.99
        p.x += p.vx
        p.y += p.vy

        if (p.x < -10) p.x = width + 10
        if (p.x > width + 10) p.x = -10
        if (p.y < -10) p.y = height + 10
        if (p.y > height + 10) p.y = -10

        const alpha = p.alpha * pulse * neonScale
        ctx.beginPath()
        ctx.arc(p.x, p.y, p.radius * pulse, 0, Math.PI * 2)
        ctx.fillStyle = p.color
        ctx.globalAlpha = alpha
        ctx.fill()

        ctx.beginPath()
        ctx.arc(p.x, p.y, p.radius * 3 * pulse, 0, Math.PI * 2)
        ctx.fillStyle = p.color
        ctx.globalAlpha = alpha * 0.15
        ctx.fill()
      }

      for (let i = 0; i < particles.length; i++) {
        for (let j = i + 1; j < particles.length; j++) {
          const a = particles[i]
          const b = particles[j]
          const dx = a.x - b.x
          const dy = a.y - b.y
          const dist = Math.sqrt(dx * dx + dy * dy)
          if (dist < connectionDistance) {
            const lineAlpha = (1 - dist / connectionDistance) * 0.15 * neonScale
            ctx.beginPath()
            ctx.moveTo(a.x, a.y)
            ctx.lineTo(b.x, b.y)
            ctx.strokeStyle = a.color
            ctx.globalAlpha = lineAlpha
            ctx.lineWidth = 0.5
            ctx.stroke()
          }
        }
      }

      if (mouse.x > 0 && mouse.y > 0) {
        for (const p of particles) {
          const dx = mouse.x - p.x
          const dy = mouse.y - p.y
          const dist = Math.sqrt(dx * dx + dy * dy)
          if (dist < 180) {
            const lineAlpha = (1 - dist / 180) * 0.25 * neonScale
            ctx.beginPath()
            ctx.moveTo(p.x, p.y)
            ctx.lineTo(mouse.x, mouse.y)
            ctx.strokeStyle = p.color
            ctx.globalAlpha = lineAlpha
            ctx.lineWidth = 0.8
            ctx.stroke()
          }
        }
      }

      ctx.globalAlpha = 1
      animFrameRef.current = requestAnimationFrame(animate)
    }

    animFrameRef.current = requestAnimationFrame(animate)

    return () => {
      cancelAnimationFrame(animFrameRef.current)
      window.removeEventListener("resize", resize)
      window.removeEventListener("mousemove", handleMouse)
      window.removeEventListener("mouseleave", handleMouseLeave)
    }
  }, [connectionDistance, createParticles, neonScale])

  return (
    <canvas
      ref={canvasRef}
      className={className ?? "absolute inset-0 z-[1]"}
      style={{ opacity: 0.6, pointerEvents: "none" }}
      aria-hidden="true"
    />
  )
})
